"""Measure the unchanged production sidecar using a task-owned verified cache."""
from __future__ import annotations
import argparse
import hashlib
import json
import os
from pathlib import Path
import queue
import re
import subprocess
import sys
import threading
import time
import wave

PINS = {
    "f16": ("ggml-parakeet-tdt-0.6b-v3-f16.bin", 1255897319, "833bffc9513b2cae867ee9e51633cfd11e4d51aaa5597c8ac02159385a2b426f"),
    "q8_0": ("ggml-parakeet-tdt-0.6b-v3-q8_0.bin", 668757119, "4d64e9e96c2792186d072fde0034df0ad670cf680a2f53069052ead827fd600e"),
}
MODEL_ID = "ggml-org/parakeet-GGUF"
REVISION = "35156454d1a39de06863303dd209fd2bed6ee079"
ROOT = Path(__file__).resolve().parent
REPO = ROOT.parent.parent


def emit(value):
    print(json.dumps(value, ensure_ascii=False), flush=True)


class Sidecar:
    def __init__(self, variant, model, cache):
        validation_start = time.perf_counter_ns()
        name, size, digest = PINS[variant]
        if model.stat().st_size != size:
            raise RuntimeError("pinned artifact size mismatch")
        h = hashlib.sha256()
        with model.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                h.update(chunk)
        if h.hexdigest() != digest:
            raise RuntimeError("pinned artifact digest mismatch")
        if not cache.resolve().is_relative_to(ROOT):
            raise RuntimeError("benchmark cache must remain inside task root")
        cache.mkdir(parents=True, exist_ok=True)
        target = cache / name
        if target.is_symlink():
            target.unlink()
        if not target.exists():
            os.link(model, target)
        elif not target.samefile(model):
            cached_hash = hashlib.sha256()
            with target.open("rb") as handle:
                for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                    cached_hash.update(chunk)
            if target.stat().st_size != size or cached_hash.hexdigest() != digest:
                raise RuntimeError("task cache artifact does not match compiled pin")
            target.unlink()
            os.link(model, target)
        manifest = {"model_id": MODEL_ID, "revision": REVISION, "file": name,
                    "sha256": digest, "size_bytes": size}
        (cache / "manifest.json").write_text(json.dumps(manifest) + "\n")
        self.variant = variant
        self.name = name
        self.events = queue.Queue()
        self.write_lock = threading.Lock()
        self.validation_ms = (time.perf_counter_ns() - validation_start) / 1e6
        self.preload_done = threading.Event()
        self.preload_ms = None
        self.preload_error = None
        self.download_observed = False
        env = {k: os.environ[k] for k in ("PATH", "HOME", "TMPDIR") if k in os.environ}
        env.update({"VOICEOUR_MODEL_CACHE": str(cache), "VOICEOUR_MODEL_VARIANT": variant,
                    "VOICEOUR_ASR_BACKEND": "parakeet", "VOICEOUR_PRELOAD": "1",
                    "VOICEOUR_IDLE_UNLOAD_MS": "0", "VOICEOUR_ASR_LOG": "error"})
        started = time.perf_counter_ns()
        self.process = subprocess.Popen([str(REPO / ".build/release/voiceour-asr")], env=env,
                                        stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        try:
            threading.Thread(target=self._read, daemon=True).start()
            threading.Thread(target=self._read_diagnostics, daemon=True).start()
            hello = self.receive(30)
            if hello.get("type") != "hello" or hello.get("protocol_version") != 1:
                raise RuntimeError(f"invalid greeting: {hello}")
            deadline = time.monotonic() + 300
            while not self.preload_done.wait(0.1):
                self.send({"type": "health", "protocol_version": 1, "request_id": "benchmark-health"})
                health = self.receive(30)
                if health.get("last_acquisition_error"):
                    raise RuntimeError(health["last_acquisition_error"])
                if time.monotonic() >= deadline:
                    raise TimeoutError("sidecar preload did not finish")
            if self.preload_error or self.preload_ms is None:
                raise RuntimeError(self.preload_error or "missing preload completion telemetry")
            if self.download_observed:
                raise RuntimeError("unexpected model acquisition in pre-cached benchmark")
            self.load_ms = self.preload_ms
            self.preload_observed_wall_ms = (time.perf_counter_ns() - started) / 1e6
            self.hello = hello
        except BaseException:
            self.close()
            raise

    def _read(self):
        for line in self.process.stdout:
            try:
                self.events.put(json.loads(line))
            except Exception as exc:
                self.events.put({"type": "invalid", "error": str(exc)})
        self.events.put({"type": "eof"})

    def _read_diagnostics(self):
        for line in self.process.stderr:
            sys.stderr.buffer.write(line)
            sys.stderr.buffer.flush()
            text = line.decode("utf8", errors="replace")
            if "VOICEOUR_PRELOAD download" in text:
                self.download_observed = True
                self.preload_error = "unexpected model acquisition in pre-cached benchmark"
                self.preload_done.set()
                self.process.terminate()
            matched = re.search(r"VOICEOUR_PRELOAD warm in (\d+)ms", text)
            if matched:
                self.preload_ms = int(matched.group(1))
                self.preload_done.set()
            elif "VOICEOUR_PRELOAD failed" in text:
                self.preload_error = text.strip()
                self.preload_done.set()

    def send(self, value):
        with self.write_lock:
            self.process.stdin.write(json.dumps(value).encode() + b"\n")
            self.process.stdin.flush()

    def receive(self, timeout):
        try:
            response = self.events.get(timeout=timeout)
        except queue.Empty:
            raise TimeoutError("sidecar response timeout") from None
        if response.get("type") in ("invalid", "eof"):
            raise RuntimeError(response)
        if response.get("protocol_version") != 1:
            raise RuntimeError("sidecar protocol mismatch")
        return response

    def transcribe(self, row):
        path = Path(row["audio_path"])
        started = time.perf_counter_ns()
        try:
            with wave.open(str(path), "rb") as audio:
                rate, channels = audio.getframerate(), audio.getnchannels()
                duration = audio.getnframes() / rate
        except (OSError, wave.Error):
            # The production sidecar owns rejection, not this measurement adapter.
            rate, channels, duration = 0, 0, 0.0
        byte_count = path.stat().st_size if path.is_file() else 0
        read_ms = (time.perf_counter_ns() - started) / 1e6
        identifier = row["id"]
        request = {"type": "transcribe", "protocol_version": 1, "request_id": identifier,
                   "audio": {"path": str(path), "format": "wav", "sample_rate_hz": rate,
                             "channels": channels, "duration_ms": round(duration * 1000), "byte_count": byte_count},
                   "expected_model": {"model_id": MODEL_ID, "revision": REVISION, "file": self.name},
                   "timeout_ms": 30000}
        self.send(request)
        timer = None
        cancel_at = [None]
        if "cancel_after_ms" in row:
            def cancel():
                cancel_at[0] = time.perf_counter_ns()
                self.send({"type": "cancel", "protocol_version": 1, "request_id": identifier})
            timer = threading.Timer(float(row["cancel_after_ms"]) / 1000, cancel)
            timer.start()
        try:
            response = self.receive(max(60.0, duration * 2 + 30))
        finally:
            if timer:
                timer.cancel()
        if response.get("request_id") != identifier:
            raise RuntimeError("sidecar returned wrong request id")
        if response["type"] == "cancelled":
            return {"type": "error", "id": identifier, "error": "cancelled", "cancelled": True,
                    "cancel_latency_ms": ((time.perf_counter_ns() - cancel_at[0]) / 1e6) if cancel_at[0] else None,
                    "fatal": False}
        if response["type"] == "error":
            fatal = response.get("code") == "inference_failed" or self.process.poll() is not None
            return {"type": "error", "id": identifier, "error": response, "fatal": fatal}
        if response["type"] != "result":
            raise RuntimeError(f"unexpected sidecar terminal: {response}")
        transcript = response["transcript"]
        return {"type": "result", "id": identifier, "text": transcript["text"], "audio_s": duration,
                "inference_ms": response["timings_ms"]["inference"], "input_read_ms": read_ms,
                "segments": transcript.get("segments"), "confidence": transcript.get("confidence"),
                "confidence_mode": transcript.get("confidence_mode"), "sidecar_timings_ms": response["timings_ms"]}

    def close(self):
        self.process.stdin.close()
        try:
            self.process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            self.process.terminate()
            try:
                self.process.wait(timeout=3)
            except subprocess.TimeoutExpired:
                self.process.kill()
                self.process.wait(timeout=3)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--variant", choices=PINS, required=True)
    parser.add_argument("--model", type=Path, required=True)
    parser.add_argument("--cache", type=Path, required=True)
    args = parser.parse_args()
    sidecar = Sidecar(args.variant, args.model, args.cache)
    emit({"type": "ready", "candidate": f"production-v3-{args.variant}", "model_id": MODEL_ID,
          "revision": REVISION, "precision": args.variant, "runtime": "voiceour-asr release, unchanged production",
          "load_ms": sidecar.load_ms, "measured_pid": sidecar.process.pid,
          "pre_spawn_validation_ms": sidecar.validation_ms,
          "preload_observed_wall_ms": sidecar.preload_observed_wall_ms,
          "preload_completion_observed": True, "download_observed": sidecar.download_observed,
          "timing_scope": "sidecar native PCM-to-ASRtext (integer-ms production telemetry); file-read outside inference"})
    try:
        for line in sys.stdin:
            request = json.loads(line)
            try:
                response = sidecar.transcribe(request)
                emit(response)
                if response.get("fatal"):
                    break
            except Exception as exc:
                fatal = isinstance(exc, (TimeoutError, RuntimeError, BrokenPipeError))
                emit({"type": "error", "id": request.get("id"), "error": str(exc), "fatal": fatal})
                if fatal:
                    break
    finally:
        sidecar.close()


if __name__ == "__main__":
    main()

