import ASRSidecarCore
import Darwin
import Dispatch
import Foundation

/// The pinned candidate identity and benchmark-only input condition.
private struct Descriptor: Decodable {
    let candidate: String
    let model_id: String
    let revision: String
    let precision: String
    let runtime: String
    let model_path: String
    let leading_silence_samples: Int
}

/// One strictly serial file request; the process retains exactly one model context.
private struct Request: Decodable {
    let id: String
    let audio_path: String
    let cancel_after_ms: Double?
}

private enum RunnerError: Error, CustomStringConvertible {
    case usage(String)
    case invalid(String)

    var description: String {
        switch self {
        case .usage(let detail), .invalid(let detail): return detail
        }
    }
}

/// Wall-clock precision is retained as Double milliseconds, without integer truncation.
private func elapsedMilliseconds(since start: UInt64) -> Double {
    Double(DispatchTime.now().uptimeNanoseconds - start) / 1_000_000.0
}

/// Uses the original stdout descriptor while native printf/log output is sent to stderr.
private func emit(_ object: [String: Any], to output: FileHandle) throws {
    let data = try JSONSerialization.data(withJSONObject: object, options: [.sortedKeys])
    try output.write(contentsOf: data)
