private struct Wave {
    let samples: [Float]
    var seconds: Double { Double(samples.count) / 16000 }

    static func read(_ path: String) throws -> Wave {
        guard path.hasPrefix("/") else { throw Failure("audio_path must be absolute") }
        let bytes = try Data(contentsOf: URL(fileURLWithPath: path))
        func u16(_ index: Int) -> UInt16 {
            UInt16(bytes[index]) | UInt16(bytes[index + 1]) << 8
        }
        func u32(_ index: Int) -> UInt32 {
            UInt32(bytes[index]) | UInt32(bytes[index + 1]) << 8 |
                UInt32(bytes[index + 2]) << 16 | UInt32(bytes[index + 3]) << 24
        }
        func tag(_ index: Int) -> String { String(decoding: bytes[index..<(index + 4)], as: UTF8.self) }
        guard bytes.count >= 12, tag(0) == "RIFF", tag(8) == "WAVE" else {
            throw Failure("Expected RIFF/WAVE file")
        }
        let end = Int(u32(4)) + 8
        guard end >= 12, end <= bytes.count else { throw Failure("Truncated RIFF payload") }
        var offset = 12
        var formatSeen = false
        var pcmRange: Range<Int>?
        while offset + 8 <= end {
            let length = Int(u32(offset + 4))
            let start = offset + 8
            guard length <= end - start else { throw Failure("Truncated WAV chunk") }
            switch tag(offset) {
            case "fmt ":
                guard !formatSeen, length >= 16 else { throw Failure("Invalid or repeated WAV fmt chunk") }
                guard u16(start) == 1, u16(start + 2) == 1, u32(start + 4) == 16000,
                      u32(start + 8) == 32000, u16(start + 12) == 2, u16(start + 14) == 16 else {
                    throw Failure("Expected 16 kHz mono signed PCM16 WAV, without resampling")
                }
                formatSeen = true
            case "data":
                guard pcmRange == nil, length > 0, length % 2 == 0 else {
                    throw Failure("Invalid or repeated WAV data chunk (never silently truncate)")
                }
                pcmRange = start..<(start + length)
            default:
                break
            }
            offset = start + length + (length % 2)
        }
        guard offset == end, formatSeen, let range = pcmRange else { throw Failure("Incomplete WAV chunks") }
        var samples = [Float](repeating: 0, count: range.count / 2)
        for index in samples.indices {
            samples[index] = Float(Int16(bitPattern: u16(range.lowerBound + index * 2))) / 32768
        }
        return Wave(samples: samples)
    }
}

private final class LocalModels {
    let source: URL
    let destination: URL
    private(set) var compilationMS: Double = 0
    private(set) var compiledComponents: [String] = []

    init(config: RunnerConfig) throws {
        source = URL(fileURLWithPath: config.model_dir, isDirectory: true)
        destination = URL(fileURLWithPath: config.compiled_dir, isDirectory: true)
        let owned = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("compiled", isDirectory: true).standardizedFileURL.path + "/"
        guard destination.standardizedFileURL.path.hasPrefix(owned) else {
            throw Failure("compiled_dir must be inside the runner's owned fluid/compiled directory")
        }
        guard FileManager.default.fileExists(atPath: source.path) else {
            throw Failure("Missing local model directory: \(source.path); acquisition is preparation-only")
        }
        try FileManager.default.createDirectory(at: destination, withIntermediateDirectories: true)
    }

    func component(_ name: String) throws -> URL {
        let local = source.appendingPathComponent(name + ".mlmodelc")
        if FileManager.default.fileExists(atPath: local.path) { return local }
        let cached = destination.appendingPathComponent(name + ".mlmodelc")
        if FileManager.default.fileExists(atPath: cached.path) { return cached }
        let package = source.appendingPathComponent(name + ".mlpackage")
        guard FileManager.default.fileExists(atPath: package.path) else {
            throw Failure("Missing local component \(name).mlmodelc or .mlpackage at \(source.path)")
        }
        let start = now()
        let temporary = try MLModel.compileModel(at: package)
        defer { try? FileManager.default.removeItem(at: temporary) }
        try FileManager.default.copyItem(at: temporary, to: cached)
        compilationMS += elapsed(start)
        compiledComponents.append(name)
        return cached
    }

    func load(_ name: String, units: MLComputeUnits, function: String? = nil) throws -> MLModel {
        let configuration = MLModelConfiguration()
        configuration.computeUnits = units
        configuration.functionName = function
        return try MLModel(contentsOf: component(name), configuration: configuration)
    }
}

private enum Engine {
    case unified(UnifiedAsrManager)
    case tdt(AsrManager)

    func transcribe(_ samples: [Float]) async throws -> String {
        switch self {
        case .unified(let manager):
            return try await manager.transcribe(samples)
        case .tdt(let manager):
            var state = try TdtDecoderState()
            return try await manager.transcribe(samples, decoderState: &state, language: .english).text
        }
    }

    func cleanup() async {
        switch self {
        case .unified(let manager): await manager.cleanup()
        case .tdt(let manager): await manager.cleanup()
        }
    }

    static func load(config: RunnerConfig, files: LocalModels) async throws -> Engine {
        let units: MLComputeUnits
        switch config.encoder_compute_units {
        case "cpuAndNeuralEngine": units = .cpuAndNeuralEngine
        case "cpuAndGPU": units = .cpuAndGPU
        case "cpuOnly": units = .cpuOnly
        default: throw Failure("Unknown encoder_compute_units: \(config.encoder_compute_units)")
        }
        let configuration = MLModelConfiguration()
        configuration.computeUnits = units
        switch config.backend {
        case "nemotron":
            let precision: UnifiedEncoderPrecision
            let encoderName: String
            switch config.precision {
            case "fp16": precision = .fp16; encoderName = "nemotron_unified_encoder"
            case "int8-encoder_fp16-decoder-joint":
                precision = .int8; encoderName = "nemotron_unified_encoder_int8"
            default: throw Failure("Nemotron precision must be explicit fp16 or int8-encoder_fp16-decoder-joint")
            }
            guard !(precision == .int8 && units == .cpuAndGPU) else {
                throw Failure("Pinned FluidAudio warns int8+GPU aborts MPSGraph; select CPU+ANE or CPU")
            }
            let sourceVocabulary = files.source.appendingPathComponent("vocab.json")
            let destinationVocabulary = files.destination.appendingPathComponent("vocab.json")
            guard FileManager.default.fileExists(atPath: sourceVocabulary.path) else { throw Failure("Missing local vocab.json") }
            if !FileManager.default.fileExists(atPath: destinationVocabulary.path) {
                try FileManager.default.copyItem(at: sourceVocabulary, to: destinationVocabulary)
            }
            // Manager loadModels(from:) expects one directory. Link only already-local compiled
            // components; the acquisition/downloading overload is deliberately never called.
            for name in [encoderName, "nemotron_unified_decoder", "nemotron_unified_joint_decision_single_step"] {
                let compiled = try files.component(name)
                let link = files.destination.appendingPathComponent(name + ".mlmodelc")
                if compiled != link, !FileManager.default.fileExists(atPath: link.path) {
                    try FileManager.default.createSymbolicLink(at: link, withDestinationURL: compiled)
                }
            }
            let manager = UnifiedAsrManager(
                configuration: configuration,
                config: UnifiedConfig(family: .nemotronMultilingual(.en)),
                encoderPrecision: precision
            )
            try await manager.loadModels(from: files.destination)
            return .unified(manager)
        case "tdt":
            let version: AsrModelVersion
            switch config.tdt_version {
            case "ultra": version = .ultra
            case "phonon2": version = .phonon2
            case "bark3": version = .bark3
            case "bark3Clean": version = .bark3Clean
            case "v3": version = .v3
            default: throw Failure("Unsupported TDT version")
            }
            guard let filename = config.vocabulary_file else { throw Failure("TDT requires vocabulary_file") }
            let raw = try JSONDecoder().decode([String: String].self,
                from: Data(contentsOf: files.source.appendingPathComponent(filename)))
            let vocabulary = Dictionary(uniqueKeysWithValues: raw.compactMap { key, value in Int(key).map { ($0, value) } })
            guard (0..<version.blankId).allSatisfy({ vocabulary[$0] != nil }) else {
                throw Failure("TDT vocabulary is missing one or more tokens below blank \(version.blankId)")
            }
            let models = AsrModels(
                encoder: try files.load("Encoder", units: units, function: config.encoder_function),
                preprocessor: try files.load("Preprocessor", units: .cpuOnly),
                decoder: try files.load("Decoder", units: .cpuOnly),
                joint: try files.load("JointDecisionv3", units: .cpuOnly),
                configuration: configuration,
                vocabulary: vocabulary,
                version: version
            )
            // A fixed 15 s export has at most 188 encoder frames * 10 emissions/frame.
            // Lift upstream's 150-token guard so fast speech cannot silently hit that cap.
            let manager = AsrManager(config: ASRConfig(
                tdtConfig: TdtConfig(maxTokensPerChunk: 2000),
                parallelChunkConcurrency: 1,
                streamingEnabled: false,
                melChunkContext: false
            ), models: models)
            return .tdt(manager)
        default:
            throw Failure("Unknown backend: \(config.backend)")
        }
    }
}

@main private struct FluidBench {
    static func main() async {
        // Preserve a dedicated protocol descriptor, then redirect *all* dependency stdout
        // (including possible C/CoreML diagnostics) to stderr before model construction.
        let descriptor = dup(STDOUT_FILENO)
        guard descriptor >= 0, dup2(STDERR_FILENO, STDOUT_FILENO) >= 0 else { exit(74) }
        let output = FileHandle(fileDescriptor: descriptor, closeOnDealloc: true)
        signal(SIGPIPE, SIG_IGN)
        AppLogger.minimumLevel = .warning
        AppLogger.mirrorsToConsole = true
        var engine: Engine?
        do {
            let arguments = Array(CommandLine.arguments.dropFirst())
            if arguments == ["--help"] {
                let message = "fluid-bench --config /absolute/config.json\nPersistent stdin requests {\"id\":\"...\",\"audio_path\":\"/absolute/16k-mono-pcm16.wav\"}. NDJSON stdout; logs stderr; EOF releases models. No capture, playback, warmup or downloads. FluidAudio pin \(fluidRevision).\n"
                try FileHandle.standardError.write(contentsOf: Data(message.utf8))
                return
            }
            guard arguments.count == 2, arguments[0] == "--config", arguments[1].hasPrefix("/") else {
                throw Failure("Usage: fluid-bench --config /absolute/config.json")
            }
            let config = try JSONDecoder().decode(RunnerConfig.self,
                from: Data(contentsOf: URL(fileURLWithPath: arguments[1])))
            guard config.leading_pad_samples >= 0 else { throw Failure("Negative leading padding") }
            let loadStart = now()
            let files = try LocalModels(config: config)
            let loaded = try await Engine.load(config: config, files: files)
            engine = loaded
            try emit(Ready(candidate: config.candidate, model_id: config.model_id,
                revision: config.revision, precision: config.precision, load_ms: elapsed(loadStart),
                compilation_ms: files.compilationMS, compiled_components: files.compiledComponents,
                preprocessing: config.preprocessing), to: output)
            var firstUse = true
            while let line = readLine(strippingNewline: true) {
                var requestID: String?
                let request: Request
                let wave: Wave
                let inputMS: Double
                do {
                    guard let data = line.data(using: .utf8), !line.contains("\0") else { throw Failure("Invalid UTF-8/NUL request") }
                    requestID = (try? JSONSerialization.jsonObject(with: data) as? [String: Any])?["id"] as? String
                    request = try JSONDecoder().decode(Request.self, from: data)
                    requestID = request.id
                    let inputStart = now()
                    wave = try Wave.read(request.audio_path)
                    inputMS = elapsed(inputStart)
                } catch {
                    try emit(ErrorRow(id: requestID, error: String(describing: error), fatal: false), to: output)
                    continue
                }
                do {
                    let start = now()
                    let samples: [Float]
                    if config.leading_pad_samples > 0 {
                        var padded = [Float](repeating: 0, count: config.leading_pad_samples)
                        padded.reserveCapacity(config.leading_pad_samples + wave.samples.count)
                        padded.append(contentsOf: wave.samples)
                        samples = padded
                    } else {
                        samples = wave.samples
                    }
                    let text = try await loaded.transcribe(samples)
                    try emit(Result(id: request.id, text: text, inference_ms: elapsed(start),
                        audio_s: wave.seconds, input_read_ms: inputMS, first_use: firstUse), to: output)
                    firstUse = false
                } catch {
                    try emit(ErrorRow(id: request.id, error: String(describing: error), fatal: true), to: output)
                    await loaded.cleanup()
                    exit(1)
                }
            }
            await loaded.cleanup()
        } catch {
            try? emit(ErrorRow(id: nil, error: String(describing: error), fatal: true), to: output)
            if let engine { await engine.cleanup() }
            exit(1)
        }
    }
}

